import { useEffect } from "react";

const SERVICE_WORKER_URL = "/sw.js";

/**
 * Registers the PWA service worker generated by vite-plugin-pwa.
 *
 * TanStack Start renders the document from `shellComponent` rather than a
 * static index.html, so the plugin has no HTML to inject its registration
 * script into (`injectRegister: false` in vite.config.ts). Registration happens
 * here instead, inside an effect, so it only ever runs in the browser.
 *
 * `registerType: 'autoUpdate'` makes the generated worker call `skipWaiting()`
 * and `clientsClaim()` (see `workbox` in vite.config.ts): a freshly deployed
 * worker takes over immediately, which fires `controllerchange` — we reload
 * once so open tabs actually run the new build.
 */
export function ServiceWorkerRegistrar() {
  useEffect(() => {
    // The worker only exists in production builds.
    if (import.meta.env.DEV) return;
    if (typeof navigator === "undefined" || !("serviceWorker" in navigator)) return;

    const container = navigator.serviceWorker;
    // A page that was already controlled means this is an update, not the very
    // first install — only updates are worth reloading for.
    const hasExistingController = Boolean(container.controller);
    let reloading = false;

    const handleControllerChange = () => {
      if (!hasExistingController || reloading) return;
      reloading = true;
      window.location.reload();
    };

    container.addEventListener("controllerchange", handleControllerChange);

    const register = () => {
      container
        .register(SERVICE_WORKER_URL, { scope: "/" })
        .then((registration) => registration.update())
        .catch((error: unknown) => {
          // Never let a registration failure break the app shell.
          console.error("[PWA] service worker registration failed", error);
        });
    };

    if (document.readyState === "complete") {
      register();
    } else {
      window.addEventListener("load", register, { once: true });
    }

    return () => {
      container.removeEventListener("controllerchange", handleControllerChange);
      window.removeEventListener("load", register);
    };
  }, []);

  return null;
}
